"use strict";(self.webpackChunklifewell_docs=self.webpackChunklifewell_docs||[]).push([["7108"],{30364(e){e.exports=JSON.parse('{"tag":{"label":"getting-started","permalink":"/tags/getting-started","allTagsPath":"/tags","count":6,"items":[{"id":"getting-started/tour","title":"A short tour","description":"The dashboard, the menu, the top bar and the one control that changes how LifeWell looks \u2014 where things are before you go looking for them.","permalink":"/getting-started/tour"},{"id":"getting-started/install-android","title":"Install on Android","description":"LifeWell on Android is a Capacitor build of the same app. Get it from Google Play, sign in with Google, and the record is the same one the web build reads.","permalink":"/getting-started/install-android"},{"id":"intro","title":"LifeWell","description":"LifeWell keeps the people and moments of your life in one place \u2014 your family and friends, what you know about them, your memories and your plans, with wellbeing around them. Web and Android, kept by you.","permalink":"/intro"},{"id":"getting-started/first-run","title":"The first run","description":"What LifeWell asks the first time you sign in \u2014 five short steps, most of them skippable, and what each answer changes.","permalink":"/getting-started/first-run"},{"id":"getting-started/tours-and-walkthrough","title":"The page tour and the walkthrough","description":"Two ways to learn LifeWell \u2014 a short page tour from the signpost button in the top bar, and How LifeWell works, six screens with real screenshots. Plus the Jobs list for long tasks.","permalink":"/getting-started/tours-and-walkthrough"},{"id":"getting-started/install-web","title":"Use LifeWell on the web","description":"Open LifeWell in any current browser, sign in with Google, and start recording. No download, no account form, nothing to configure.","permalink":"/getting-started/install-web"}],"unlisted":false}}')}}]);